'use strict';
const API='https://ekcbgsfmlikfsxyewpff.supabase.co',KEY='sb_publishable_Uw1w3YwC3Aei-MG1OGUdjg_RovVoRuP',$=s=>document.querySelector(s);let session=null,requests=[],services=[];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signupButton=document.createElement('button');signupButton.type='button';signupButton.className='secondary';signupButton.textContent='Create admin login';signupButton.style.marginTop='15px';$('#login-form').append(signupButton);
signupButton.onclick=async()=>{if(!$('#email').reportValidity())return;if($('#password').value.length<12){$('#auth-status').textContent='Choose a password of at least 12 characters.';return}signupButton.disabled=true;try{const data=await auth('signup?redirect_to='+encodeURIComponent(location.origin+'/admin.html'),{email:$('#email').value.trim(),password:$('#password').value});$('#password').value='';if(data.access_token){saveSession(data);await enter()}else{$('#auth-status').textContent='Check your email to confirm your login, then return here to sign in. Only emails added under Team & alerts get admin access. If the account already exists, use password reset.'}}catch(err){$('#auth-status').textContent=err.message}finally{signupButton.disabled=false}};
const day=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lusaka',year:'numeric',month:'2-digit',day:'2-digit'}).format(d||new Date());
async function auth(path,payload,access){const r=await fetch(API+'/auth/v1/'+path,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json',...(access?{Authorization:'Bearer '+access}:{})},body:JSON.stringify(payload),signal:AbortSignal.timeout(15000)});const data=r.status===204?{}:await r.json();if(!r.ok)throw Error(data.msg||data.error_description||data.message||'Sign-in failed.');return data}
function saveSession(data){session={...data,expires_at:Date.now()/1000+(data.expires_in||3600)};sessionStorage.setItem('bloom-admin-session',JSON.stringify(session))}
async function token(){if(!session)throw Error('Please sign in.');if(session.expires_at<Date.now()/1000+60)saveSession(await auth('token?grant_type=refresh_token',{refresh_token:session.refresh_token}));return session.access_token}
async function db(path,options={}){const access=await token();const r=await fetch(API+'/rest/v1/'+path,{...options,headers:{apikey:KEY,Authorization:'Bearer '+access,'Content-Type':'application/json',Prefer:'return=representation'},signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Could not complete the request. Check your connection and admin access.');return r.status===204?null:r.json()}
function signout(){session=null;sessionStorage.removeItem('bloom-admin-session');requests=[];services=[];$('#requests').replaceChildren();$('#services').replaceChildren();$('#dashboard').hidden=true;$('#logout').hidden=true;$('#reset-panel').hidden=true;$('#login').hidden=false;$('#setup-guide').hidden=false}
async function enter(){const members=await db('bloom_admins?select=user_id');if(!members.length){signout();throw Error('This account is not approved for studio admin access.')}$('#setup-guide').hidden=true;$('#login').hidden=true;$('#dashboard').hidden=false;$('#logout').hidden=false;await load()}
$('#login-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;$('#auth-status').textContent='Signing in…';try{saveSession(await auth('token?grant_type=password',{email:$('#email').value.trim(),password:$('#password').value}));$('#password').value='';await enter();$('#auth-status').textContent=''}catch(err){$('#auth-status').textContent=err.message}finally{e.submitter.disabled=false}};
$('#logout').onclick=async()=>{try{await auth('logout',{},await token())}catch{}signout()};
$('#reset').onclick=async()=>{if(!$('#email').reportValidity())return;$('#reset').disabled=true;try{await auth('recover?redirect_to='+encodeURIComponent(location.origin+'/admin.html'),{email:$('#email').value.trim()});$('#auth-status').textContent='If this email has an account, a password reset link will arrive shortly.'}catch(err){$('#auth-status').textContent=err.message}finally{$('#reset').disabled=false}};
$('#password-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const r=await fetch(API+'/auth/v1/user',{method:'PUT',headers:{apikey:KEY,Authorization:'Bearer '+await token(),'Content-Type':'application/json'},body:JSON.stringify({password:$('#new-password').value})});if(!r.ok)throw Error('Password could not be updated. Request a new reset link.');$('#new-password').value='';$('#reset-panel').hidden=true;await enter()}catch(err){$('#reset-status').textContent=err.message}finally{e.submitter.disabled=false}};
async function load(){$('#refresh').disabled=true;$('#dashboard-status').textContent='Loading studio records…';try{[requests,services]=await Promise.all([db('bloom_appointment_requests?select=*&order=created_at.desc&limit=1000'),db('bloom_services?select=*&order=sort_order')]);$('#pending').textContent=requests.filter(r=>r.status==='pending').length;$('#upcoming').textContent=requests.filter(r=>r.status==='confirmed'&&r.preferred_date>=day()).length;$('#today').textContent=requests.filter(r=>day(new Date(r.created_at))===day()).length;$('#completed').textContent=requests.filter(r=>r.status==='completed').length;renderRequests();renderServices();$('#dashboard-status').textContent=requests.length===1000?'Showing the most recent 1,000 requests.':'Studio records are up to date.'}catch(err){$('#dashboard-status').textContent=err.message}finally{$('#refresh').disabled=false}}
function renderRequests(){const q=$('#search').value.trim().toLowerCase(),status=$('#status-filter').value,date=$('#date-filter').value;const matches=requests.filter(r=>(status==='all'||r.status===status)&&(!date||r.preferred_date===date)&&[r.customer_name,r.email,r.phone,r.service_name,r.id].join(' ').toLowerCase().includes(q));$('#requests').innerHTML=matches.length?matches.map(r=>`<article class="card"><h3>${esc(r.customer_name)} <span class="badge">${esc(r.status)}</span></h3><div class="meta">${esc(r.service_name)} · ${esc(r.preferred_date)} at ${esc(r.preferred_time.slice(0,5))} (Zambia)<br>Recorded price: ${r.price_zmw==null?'Not recorded':'K'+esc(r.price_zmw)} · ${esc(r.duration_minutes??'—')} minutes<br>Phone: ${esc(r.phone)}<br>Email: ${esc(r.email)}<br>Follow-up permission: ${r.followup_consent?'Yes':'No'}<br>Reference: ${esc(r.id)}</div><div class="row"><label>Status <select data-status="${esc(r.id)}">${['pending','confirmed','cancelled','completed'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><button data-save="${esc(r.id)}">Save status</button>${r.followup_consent?`<button data-whatsapp="${esc(r.id)}" class="secondary">Prepare WhatsApp message ↗</button>`:'<small>No permission for follow-up contact.</small>'}</div></article>`).join(''):'<p>No appointment requests match these filters.</p>'}
$('#requests').onclick=async e=>{const save=e.target.closest('[data-save]'),wa=e.target.closest('[data-whatsapp]');if(save){const id=save.dataset.save,select=[...document.querySelectorAll('[data-status]')].find(x=>x.dataset.status===id);save.disabled=true;try{const rows=await db('bloom_appointment_requests?id=eq.'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({status:select.value})});if(!rows.length)throw Error('No appointment was updated.');await load();$('#dashboard-status').textContent='Status saved. No message was sent automatically.'}catch(err){$('#dashboard-status').textContent=err.message;save.disabled=false}}if(wa){const r=requests.find(x=>x.id===wa.dataset.whatsapp);if(!r?.followup_consent)return;const phone=r.phone.replace(/\D/g,'');if(!r.phone.trim().startsWith('+')||phone.length<8||phone.length>15){$('#dashboard-status').textContent='The customer phone needs an international country code beginning with +.';return}const text=`Hello ${r.customer_name}, this is Glow Bloom about your ${r.service_name} request for ${r.preferred_date} at ${r.preferred_time.slice(0,5)} (Zambia time). Current status: ${r.status}. Reference: ${r.id}.`;window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')}};
function renderServices(){$('#services').innerHTML=services.map((s,i)=>`<form class="card service-form" data-index="${i}"><h3>${esc(s.name)}</h3><p>${esc(s.category)}</p><div class="two"><label>Price (ZMW)<input name="price" type="number" step="0.01" min="0.01" max="99999999" required value="${esc(s.price_zmw)}"></label><label>Duration (minutes)<input name="duration" type="number" step="1" min="15" max="480" required value="${esc(s.duration_minutes)}"></label></div><label>Description<textarea name="description" rows="3" required maxlength="1000">${esc(s.description)}</textarea></label><label class="toggle"><input name="active" type="checkbox" ${s.active?'checked':''}>Available on website</label><p><button>Save treatment</button></p></form>`).join('')}
$('#services').onsubmit=async e=>{e.preventDefault();const f=e.target,s=services[Number(f.dataset.index)],data=new FormData(f),button=e.submitter;button.disabled=true;try{const rows=await db('bloom_services?name=eq.'+encodeURIComponent(s.name),{method:'PATCH',body:JSON.stringify({price_zmw:Number(data.get('price')),duration_minutes:Number(data.get('duration')),description:data.get('description').trim(),active:data.get('active')==='on'})});if(!rows.length)throw Error('Treatment was not updated.');services[Number(f.dataset.index)]=rows[0];$('#dashboard-status').textContent='Treatment saved. Customers see the change when they refresh.'}catch(err){$('#dashboard-status').textContent=err.message}finally{button.disabled=false}};
$('#refresh').onclick=load;['#search','#date-filter','#status-filter'].forEach(s=>$(s).addEventListener('input',renderRequests));$('#clear').onclick=()=>{$('#search').value='';$('#date-filter').value='';$('#status-filter').value='all';renderRequests()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#appointments').hidden=b.dataset.tab!=='appointments';$('#treatments').hidden=b.dataset.tab!=='treatments'});
(async()=>{try{const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('access_token')){saveSession({access_token:hash.get('access_token'),refresh_token:hash.get('refresh_token'),expires_in:Number(hash.get('expires_in')||3600)});history.replaceState(null,'',location.pathname);if(hash.get('type')==='recovery'){$('#login').hidden=true;$('#reset-panel').hidden=false;return}await enter();return}const stored=sessionStorage.getItem('bloom-admin-session');if(stored){session=JSON.parse(stored);await enter()}}catch(err){signout();$('#auth-status').textContent=err.message}})();
